216	//  SOFTWARE-PIPELINED single-CTA batch GEMM: D[M,N] = Σ_k A[m,k]·B[n,k], bf16
217	//  operands (accessor-sourced + Major-K staged), fp32 accumulator, ASCENDING-k.
218	//  One warpgroup (threads 0..127) issues the wgmma; all `nthreads` stage. The
219	//  staging of tile k+1 OVERLAPS the async wgmma on tile k (a kMbTcStages-deep
220	//  smem ring buffer hides the HBM-acts latency the dW K-loop (K=T=B·kSeq) is
221	//  bound by — every k-step pulls fresh operands from HBM). NUMERICS are
222	//  byte-identical to the old serial form: the accumulator is the SAME fp32
223	//  WgmmaAccum, issued in the SAME ascending-k order with ScaleD=0 on k=0 then
224	//  ScaleD=1 — only the OVERLAP of independent stages changes, never the math.
225	//  So the 0.08 per-tensor parity AND A/A/A bit-determinism hold by construction.
226	//  (Kept the name `tc_gemm_block_unpipelined` so the dozens of call sites + the
227	//  decoder-mirror lineage are untouched; "unpipelined" is now historical.)
228	//  MaxAtomsM bounds the register accumulator (compile-time). n_real<=N
229	//  suppresses ragged pad columns. smemA/smemB are the RING BASES (kMbTcStages
230	//  tiles each, contiguous): slot s lives at smemA + s*kMbTcSmemA1.
231	// ════════════════════════════════════════════════════════════════════════
232	template <int N, int MaxAtomsM, typename SrcA, typename SrcB, typename Out>
233	__device__ void tc_gemm_block_unpipelined(
234	        int mbase0, int m_atoms, int n_real, int k_steps,
235	        SrcA srcA, SrcB srcB, Out out,
236	        __nv_bfloat16* smemA, __nv_bfloat16* smemB) {
237	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
238	    const int tid = threadIdx.x;
239	    const int nthreads = blockDim.x;
240	    const bool in_wg0 = (tid < 128);
241	    const int tid_wg = tid & 127;
242	    constexpr int S = kMbTcStages;
243	
244	    wgs::WgmmaAccum<N> acc[MaxAtomsM];
245	
246	    // Stage tile `k` of atom `mbase` into ring slot `k % S`.
247	    auto stage_k = [&] (int mbase, int k) {
248	        const int s = k % S;
249	        stage_kmajor_tile<wgs::kWgmmaAtomM>(
250	            smemA + (int64_t)s * kMbTcSmemA1, k * wgs::kWgmmaAtomK,
251	            [&] (int mn, int kk) { return srcA(mbase + mn, kk); }, tid, nthreads);
252	        stage_kmajor_tile<N>(
253	            smemB + (int64_t)s * kMbTcSmemB1, k * wgs::kWgmmaAtomK,
254	            [&] (int mn, int kk) { return srcB(mn, kk); }, tid, nthreads);
255	    };
256	    // Issue the wgmma reading ring slot `k % S` into acc[a] (ScaleD per k).
257	    auto issue_k = [&] (int a, int k) {
258	        const int s = k % S;
259	        wgs::SmemDesc dA = wgs::make_desc_A_kmajor<wgs::kWgmmaAtomM, wgs::kSwizzleNone>(
260	            smemA + (int64_t)s * kMbTcSmemA1);
261	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor<N, wgs::kSwizzleNone>(
262	            smemB + (int64_t)s * kMbTcSmemB1);
263	        if (k == 0) wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/0, 0, 0>(acc[a], dA, dB);
264	        else        wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/1, 0, 0>(acc[a], dA, dB);
265	    };
266	
267	    #pragma unroll 1
268	    for (int a = 0; a < m_atoms; ++a) {
269	        const int mbase = mbase0 + a * wgs::kWgmmaAtomM;
270	        // ── Prologue: stage tile 0 into slot 0; make it visible; fence. ──
271	        stage_k(mbase, 0);
272	        __syncthreads();                 // tile 0 visible to the wgmma below
273	        if (in_wg0) wgs::wgmma_fence();
274	        // ── Steady state (S=2 single-in-flight double-buffer): issue wgmma(k)
275	        //    on the already-staged slot k&1 (async), THEN stage tile k+1 into the
276	        //    OTHER slot (k+1)&1 — its HBM operand loads run CONCURRENTLY with the
277	        //    async MMA — THEN wait_group<0> (wgmma(k) done reading slot k&1) and
278	        //    __syncthreads (stage(k+1) visible AND slot k&1 reuse-safe for k+2).
279	        //    Invariant: stage(k+1)'s slot was last read by wgmma(k-1), retired by
280	        //    iter k-1's wait+sync; the per-iter wait_group<0> is load-bearing (it
281	        //    is what makes a slot reusable). S=1 collapses to the serial path
282	        //    (issue → stage(none for k+1 since stages share a slot)… handled
283	        //    below): for S==1 we stage k+1 into the SAME slot AFTER the wait, so
284	        //    it is bit-identical to the old per-k stage→sync→issue→wait. ─────────
285	        #pragma unroll 1
286	        for (int k = 0; k < k_steps; ++k) {
287	            if (in_wg0) {
288	                issue_k(a, k);
289	                wgs::wgmma_commit_group();
290	            }
291	            if (S > 1) {
292	                // Double-buffer: prefetch k+1 into the other slot, overlapping wgmma(k).
293	                if (k + 1 < k_steps) stage_k(mbase, k + 1);
294	                if (in_wg0) wgs::wgmma_wait_group<0>();   // wgmma(k) done reading slot k&1
295	                __syncthreads();                          // stage(k+1) visible; slot k&1 free
296	            } else {
297	                // Serial (S==1, single slot): wait, then stage next into the slot.
298	                if (in_wg0) wgs::wgmma_wait_group<0>();
299	                __syncthreads();                          // wgmma(k) done reading the slot
300	                if (k + 1 < k_steps) { stage_k(mbase, k + 1); __syncthreads(); }
301	            }
302	        }
303	        if (in_wg0) {
304	            #pragma unroll
305	            for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
306	                int row, col;
307	                wgs::wgmma_frag_decode(tid_wg, i, N, row, col);
308	                if (col < n_real) out(mbase + row, col, acc[a].c[i]);
309	            }
310	        }
311	        __syncthreads();
312	    }
313	#else
314	    (void)mbase0; (void)m_atoms; (void)n_real; (void)k_steps;
315	    (void)srcA; (void)srcB; (void)out; (void)smemA; (void)smemB;
316	#endif
